  "Terminou o turno e está esperando {0} shells terminarem. A cada um que termina, o agente recebe o resultado.": "টার্ন শেষ করে {0}টি শেল শেষ হওয়ার অপেক্ষায় আছে। প্রতিটি শেষ হলেই এজেন্ট তার রেজাল্ট পায়।",
  "Terminou o turno e está esperando o shell terminar. Quando ele terminar, o agente recebe o resultado.": "টার্ন শেষ করে শেল শেষ হওয়ার অপেক্ষায় আছে। শেষ হলেই এজেন্ট রেজাল্ট পায়।",
  "Comendo pipoca e assistindo ao terminal": "পপকর্ন খাচ্ছে আর টার্মিনাল দেখছে",
  "Até 3 min: recosta na cadeira com um balde de pipoca e assiste ao terminal como se fosse um filme.": "৩ মিনিট পর্যন্ত: চেয়ারে হেলান দিয়ে এক বালতি পপকর্ন নিয়ে টার্মিনাল দেখে যেন সিনেমা।",
  "A pipoca acabou: girando na cadeira": "পপকর্ন শেষ: চেয়ারে ঘুরছে",
  "De 3 a 10 min: a pipoca acaba; braços cruzados, dedos batendo e, de vez em quando, um giro completo na cadeira.": "৩ থেকে ১০ মিনিট: পপকর্ন শেষ; হাত বাঁধা, আঙুল ঠুকছে আর মাঝে মাঝে চেয়ারে পুরো এক পাক।",
  "Já tem teia de aranha na cadeira": "চেয়ারে ইতিমধ্যেই মাকড়সার জাল ধরেছে",
  "Depois de 10 min: aparece uma teia de aranha na cadeira (ela cresce depois de 20 min) e escapa um bocejo.": "১০ মিনিট পর: চেয়ারে মাকড়সার জাল দেখা যায় (২০ মিনিট পর বড় হয়) আর একটা হাই উঠে আসে।",
