  "Este subagente roda em segundo plano: o terminal só mostra o pedido depois que você responder aqui ou escolher “Responder no terminal”.": "এই সাবএজেন্ট ব্যাকগ্রাউন্ডে চলছে: আপনি এখানে উত্তর দিলে বা “টার্মিনালে উত্তর দিন” বেছে নিলে তবেই টার্মিনালে অনুরোধ দেখা যায়।",
