  "Pedido feito às {0}. Sem resposta aqui até {1}, o AgentForge devolve o pedido ao terminal.": "{0} টায় অনুরোধ করা হয়েছে। {1}-এর মধ্যে এখানে উত্তর না পেলে, AgentForge অনুরোধটি টার্মিনালে ফিরিয়ে দেবে।",
