  "ao vivo (mod do AgentForge)": "লাইভ (AgentForge mod)",
  "Recomendado: instala o mod do AgentForge no Claude Code (2.1.287 ou mais novo), que passa o uso de 5 h e da semana ao vivo. Rode na pasta do AgentForge, no computador onde o Claude Code roda; nas sessões já abertas, `/reload-plugins`.": "প্রস্তাবিত: Claude Code-এ (2.1.287 বা নতুন সংস্করণ) AgentForge mod ইনস্টল করুন, যা 5 ঘণ্টা ও সাপ্তাহিক ব্যবহার লাইভ পাঠায়। AgentForge ফোল্ডারে, যে কম্পিউটারে Claude Code চলে সেখানে চালান; আগে থেকে খোলা সেশনে `/reload-plugins`।",
  "No Claude Code anterior ao 2.1.287: liga um tap na linha de status, que passa os mesmos números ao vivo.": "2.1.287-এর পুরনো Claude Code-এ: status line-এ একটি tap লাগান, যা একই নম্বরগুলো লাইভ পাঠায়।",
  "Sem instalar nada: rode `/usage` no Claude Code desta conta para atualizar o cache (os números envelhecem até a próxima vez).": "কিছু ইনস্টল না করেই: ক্যাশ রিফ্রেশ করতে এই অ্যাকাউন্টের Claude Code-এ `/usage` চালান (পরের বার পর্যন্ত নম্বরগুলো পুরনো হয়ে থাকে)।",
