  "{0}: sem dados": "{0}: ডেটা নেই",
  "{0}: a janela já renovou depois da última leitura; o uso atual é desconhecido.": "{0}: শেষ পড়ার পর উইন্ডো রিনিউ হয়েছে; বর্তমান ব্যবহার অজানা।",
