  "Antes de mexer, vale entender como esse fluxo está montado hoje.": "কিছু স্পর্শ করার আগে, এই ফ্লোটি আজ কীভাবে তৈরি তা বোঝা ভালো।",
  "O mais seguro é cobrir com um teste primeiro e depois ajustar o código.": "সবচেয়ে নিরাপদ পদক্ষেপ হলো প্রথমে টেস্ট দিয়ে কভার করা, তারপর কোড ঠিক করা।",
  "Acho que o problema está no cálculo; vou conferir quem chama essa função.": "মনে হয় সমস্যাটা হিসাবে; এই ফাংশনটি কে ডাকে তা দেখবো।",
  "Dá para resolver com uma mudança pequena, sem quebrar a API existente.": "বিদ্যমান API না ভেঙে ছোট একটি পরিবর্তনেই এটি ঠিক করা যায়।",
  "Preciso checar se outros lugares dependem desse comportamento.": "অন্য জায়গাগুলো এই আচরণের উপর নির্ভর করে কিনা দেখতে হবে।",
  "Pronto! Ajustei o necessário e os testes passaram.": "হয়ে গেছে! যা দরকার ছিল ঠিক করে দিয়েছি, টেস্ট পাস করেছে।",
  "Feito. A mudança ficou pequena e coberta por testes.": "হয়ে গেছে। পরিবর্তনটি ছোট এবং টেস্ট দিয়ে কভার করা।",
  "Concluí a tarefa; deixei tudo verde no build e nos testes.": "টাস্ক সম্পন্ন; বিল্ড ও টেস্ট সব সবুজ।",
  "Terminei. Se quiser, posso abrir um PR com essas mudanças.": "শেষ। চাইলে এই পরিবর্তনগুলো দিয়ে PR খুলতে পারি।",
