  "hook de permissão antigo: {0} (rode npm run hooks:uninstall depois de conferir)": "পুরোনো পারমিশন হুক: {0} (দেখার পর npm run hooks:uninstall চালান)",
  "{0}: não aparece instalado na lista do Claude Code": "{0}: Claude Code-এর তালিকায় ইনস্টল দেখাচ্ছে না",
  "{0}: instalado, mas desligado (claude plugin enable {1})": "{0}: ইনস্টল আছে, কিন্তু বন্ধ (claude plugin enable {1})",
  "{0}: o Claude Code registra a versão {1}, não a {2} (o manifesto em mod/ está com outra versão?)": "{0}: Claude Code সংস্করণ {1} রেকর্ড করে, {2} নয় (mod/-এর manifest-এ কি ভিন্ন সংস্করণ আছে?)",
  "rode npm run mod:install para mandar mensagens pelo escritório (plugin {0})": "অফিস থেকে বার্তা পাঠাতে npm run mod:install চালান (প্লাগইন {0})",
  "ainda com o nome antigo ({0}); o docker:up não troca sozinho: rode npm run mod:install": "এখনও পুরোনো নামে ({0}); docker:up নিজে বদলায় না: npm run mod:install চালান",
  "o mod está instalado, mas o marketplace {0} sumiu; rode npm run mod:install": "মড ইনস্টল আছে, কিন্তু marketplace {0} নেই; npm run mod:install চালান",
  "o mod vem de outra pasta ({0}), então não foi atualizado; para usar esta: npm run mod:install": "মডটি অন্য একটি ফোল্ডার ({0}) থেকে এসেছে, তাই এটা আপডেট হয়নি; এটা ব্যবহার করতে: npm run mod:install",
  "marketplace {0}: catálogo relido": "মার্কেটপ্লেস {0}: ক্যাটালগ আবার লোড হয়েছে",
