  "marketplace {0}: outra origem ({1}); npm run mod:install aponta para esta pasta": "মার্কেটপ্লেস {0}: অন্য উৎস ({1}); npm run mod:install এটাকে এই ফোল্ডারে নির্দেশ করে",
  "{0}: não instalado": "{0}: ইনস্টল করা নেই",
  "instalado{0}": "ইনস্টল হয়েছে{0}",
