  "JSON inválido; nada foi alterado": "ভুল JSON; কিছু বদলানো হয়নি",
  "o arquivo mudou desde a leitura; nada foi alterado, rode o comando de novo": "পড়ার পর ফাইল বদলে গেছে; কিছু বদলানো হয়নি, কমান্ডটি আবার চালান",
  "~ ~/.{0} (nome antigo) vai para ~/.agentforge (simulação: nada movido)": "~ ~/.{0} (পুরনো নাম) ~/.agentforge-এ যাবে (ড্রাই রান: কিছু সরানো হয়নি)",
  " (na frente de: {0})": " (সামনে: {0})",
  " (sem statusline original)": " (আসল statusline নেই)",
  "não instalado (statusline atual: {0})": "ইনস্টল করা নেই (বর্তমান statusline: {0})",
  "não instalado (sem statusline)": "ইনস্টল করা নেই (statusline নেই)",
  "! {0}: o tap aponta para {1}; rode npm run usage:install para atualizar": "! {0}: ট্যাপ {1}-এর দিকে নির্দেশ করে; আপডেট করতে npm run usage:install চালান",
  "último uso capturado há {0}{1}{2}": "সর্বশেষ ব্যবহার {0} আগে ধরা পড়েছে{1}{2}",
  " · semana {0}%": " · সপ্তাহ {0}%",
  "nenhum uso capturado ainda (o Claude Code envia os limites depois da primeira resposta numa sessão aberta)": "এখনো কোনো ব্যবহার ধরা পড়েনি (খোলা সেশনে প্রথম উত্তরের পর Claude Code লিমিট পাঠায়)",
  "nenhum uso capturado": "কোনো ব্যবহার ধরা পড়েনি",
  "Pronto. Os números aparecem no AgentForge depois da próxima resposta de cada sessão. Sessões já": "হয়ে গেছে। প্রতিটি সেশনের পরের উত্তরের পর সংখ্যাগুলো AgentForge-এ দেখা যাবে। যেসব সেশন ইতিমধ্যে",
  "abertas costumam recarregar o settings.json sozinhas; se o uso não aparecer, reabra a sessão.": "খোলা আছে সেগুলো সাধারণত নিজে থেকেই settings.json আবার লোড করে; ব্যবহার না দেখালে সেশনটি আবার খুলুন।",
  "Uso capturado em {0}. Para desfazer: npm run usage:uninstall": "ব্যবহার {0}-এ ধরা হয়। বাতিল করতে: npm run usage:uninstall",
