// scripts/codex-bridge.ts
  "Uso: npm run codex:bridge [-- opções]\n\nEntrega as mensagens do escritório às sessões do Codex quando o AgentForge roda no Docker (deixe rodando no computador).\n\nOpções:\n  --port <n>   porta do AgentForge (padrão: AGENTFORGE_PORT ou {0})\n  --once       faz uma rodada só e sai\n  -h, --help   mostra esta ajuda\n\nBinário do Codex: AGENTFORGE_CODEX_BIN ou `codex` do PATH.": "ব্যবহার: npm run codex:bridge [-- অপশন]\n\nAgentForge Docker-এ চললে অফিসের বার্তা Codex সেশনগুলোতে পৌঁছে দেয় (কম্পিউটারে চালু রাখুন)।\n\nঅপশন:\n  --port <n>   AgentForge পোর্ট (ডিফল্ট: AGENTFORGE_PORT বা {0})\n  --once       একবার চালিয়ে বেরিয়ে যায়\n  -h, --help   এই সহায়তা দেখায়\n\nCodex বাইনারি: AGENTFORGE_CODEX_BIN বা PATH থেকে `codex`।",
