  "Entregando as mensagens do AgentForge (http://127.0.0.1:{0}) às sessões do Codex com {1}, e começando os agentes novos pedidos no escritório. Ctrl+C para parar.": "AgentForge-এর বার্তা (http://127.0.0.1:{0}) {1} দিয়ে Codex সেশনগুলোতে পৌঁছে দিচ্ছে, এবং অফিসে অনুরোধ করা নতুন এজেন্টগুলো শুরু করছে। থামাতে Ctrl+C।",
  "Sem o Codex (codex no PATH ou AGENTFORGE_CODEX_BIN): só começo os agentes novos pedidos no AgentForge (http://127.0.0.1:{0}). Ctrl+C para parar.": "Codex নেই (PATH-এ codex বা AGENTFORGE_CODEX_BIN): শুধু AgentForge-এ (http://127.0.0.1:{0}) অনুরোধ করা নতুন এজেন্টগুলো শুরু করছে। থামাতে Ctrl+C।",
  "Agentes novos rodam em segundo plano com {0} --bg (pasta confiável; senão, no app do Claude).": "নতুন এজেন্টগুলো ব্যাকগ্রাউন্ডে {0} --bg দিয়ে চলে (বিশ্বস্ত ফোল্ডার; নইলে Claude অ্যাপে)।",
  "Sem o claude no PATH (ou AGENTFORGE_CLAUDE_BIN): agentes novos abrem no app do Claude e esperam o Enter.": "PATH-এ claude নেই (বা AGENTFORGE_CLAUDE_BIN): নতুন এজেন্টগুলো Claude অ্যাপে খুলে Enter-এর জন্য অপেক্ষা করে।",
