  "acesso remoto configurado, mas sem a CA local: rode npm run remote:setup.": "রিমোট অ্যাক্সেস কনফিগার করা আছে, কিন্তু লোকাল CA নেই: npm run remote:setup চালান।",
  "Acesso remoto: certificado do servidor renovado ({0}).": "রিমোট অ্যাক্সেস: সার্ভার সার্টিফিকেট নবায়ন হয়েছে ({0})।",
  "Acesso remoto: monta {0} em {1}, somente leitura.": "রিমোট অ্যাক্সেস: {0}-কে {1}-এ মাউন্ট করে, শুধু পড়ার জন্য।",
