  "[remote-mdns] sem AGENTFORGE_REMOTE_NAME válido no .env: rode npm run remote:setup.": "[remote-mdns] .env-এ বৈধ AGENTFORGE_REMOTE_NAME নেই: npm run remote:setup চালান।",
  "[remote-mdns] sem rede: anúncio suspenso.": "[remote-mdns] নেটওয়ার্ক নেই: ঘোষণা স্থগিত।",
  "[remote-mdns] {0} sem suporte: use o IP ou um endereço no DNS do roteador.": "[remote-mdns] {0} সমর্থিত নয়: IP বা রাউটারের DNS-এ থাকা একটি ঠিকানা ব্যবহার করুন।",
