  "[remote-mdns] anunciando {0}.local -> {1}": "[remote-mdns] {0}.local -> {1} ঘোষণা করছে",
// scripts/remote-setup.ts
  "Uso: npm run remote:setup [-- opções]\n\nLiga o acesso pelo celular (https://<nome>.local) com usuário, senha e HTTPS.\n\n  --user <nome>        usuário do login (padrão: o seu usuário do sistema)\n  --name <nome>        endereço <nome>.local (padrão: agentforge)\n  --domain <endereço>  endereço próprio, ex.: meuclaude.home (precisa de uma entrada no DNS do roteador)\n  --port <n>           porta no computador (padrão: 443 se estiver livre, senão 4748)\n  --allow <lista>      o que o celular pode fazer: permissions, messages, terminal, spawn, none (padrão: permissions)\n  --password-stdin     lê a senha da entrada padrão (automação), em vez de perguntar\n  --no-service         não instala o serviço do anúncio <nome>.local (rode npm run remote:mdns você mesmo)\n  --off                desliga o acesso pelo celular (tira as linhas do .env e o serviço; mantém a CA)": "ব্যবহার: npm run remote:setup [-- অপশন]\n\nইউজারনেম, পাসওয়ার্ড ও HTTPS দিয়ে ফোন অ্যাক্সেস (https://<name>.local) চালু করে।\n\n  --user <name>        লগইন ইউজারনেম (ডিফল্ট: আপনার সিস্টেম ইউজারনেম)\n  --name <name>        ঠিকানা <name>.local (ডিফল্ট: agentforge)\n  --domain <address>   নিজের ঠিকানা, যেমন: myclaude.home (রাউটারের DNS-এ একটি এন্ট্রি দরকার)\n  --port <n>           কম্পিউটারের পোর্ট (ডিফল্ট: খালি থাকলে ৪৪৩, নইলে ৪৭৪৮)\n  --allow <list>       ফোন যা যা করতে পারবে: permissions, messages, terminal, spawn, none (ডিফল্ট: permissions)\n  --password-stdin     জিজ্ঞাসা না করে স্ট্যান্ডার্ড ইনপুট থেকে পাসওয়ার্ড পড়ে (অটোমেশন)\n  --no-service         <name>.local ঘোষণার সার্ভিস ইনস্টল করে না (নিজে npm run remote:mdns চালান)\n  --off                ফোন অ্যাক্সেস বন্ধ করে (.env থেকে লাইনগুলো ও সার্ভিস সরায়; CA রাখে)",
  "falta o valor de {0}": "{0}-এর মান নেই",
  "opção desconhecida: {0}": "অজানা অপশন: {0}",
  "porta inválida": "ভুল পোর্ট",
